#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DB="$ROOT/database"

# The eight numbered SQL modules are the only deployable schema sources.
modules=(
  01_foundation.sql
  02_operations_reconciliation.sql
  03_read_apis.sql
  04_membership_sessions.sql
  05_menu_management.sql
  06_menu_options.sql
  07_inventory.sql
  08_settings.sql
)

{
  printf '%s\n' \
    '-- Fore generated test rebuild. DESTRUCTIVE: TEST DATABASE ONLY.' \
    '-- Generated by tool/build_install.sh; do not run on a database with real data.'
  for source in dev/reset_schema.sql "${modules[@]}"; do
    printf '\n-- >>> SOURCE: database/%s\n' "$source"
    cat "$DB/$source"
  done
} > "$DB/dev/rebuild_test_database.sql"

perl -0pi -e 's/(?:\r?\n)+\z/\n/' "$DB/dev/rebuild_test_database.sql"

echo 'Generated database/dev/rebuild_test_database.sql from the eight numbered schema modules.'
